// A StatusOr<T> holds either a usable value of type T, or an error Status
// explaining why such a value is not present. Callers can inspect ok() (or the
// bool conversion) before accessing the value.

#pragma once

#include <new>
#include <type_traits>
#include <utility>

#include "ray/common/status.h"
#include "ray/util/logging.h"

namespace ray {

template <typename T>
class StatusOr {
 public:
  using value_type = T;

  // Default constructor. Constructs an instance holding a
  // default-constructed value with an OK status.
  StatusOr() : status_(Status::OK()), has_value_(true) { new (&value_) T(); }

  // Constructs an instance holding an error status. Implicit on purpose so a
  // `Status` can be returned where a `StatusOr<T>` is expected.
  StatusOr(const Status &status)  // NOLINT
      : status_(status), has_value_(false) {
    RAY_CHECK(!status_.ok())
        << "Cannot construct a StatusOr with an OK status and no value.";
  }
  StatusOr(Status &&status)  // NOLINT
      : status_(std::move(status)), has_value_(false) {
    RAY_CHECK(!status_.ok())
        << "Cannot construct a StatusOr with an OK status and no value.";
  }

  // Constructs an instance holding a value. Implicit on purpose so a `T` can be
  // returned where a `StatusOr<T>` is expected.
  StatusOr(const T &value)  // NOLINT
      : status_(Status::OK()), has_value_(true) {
    new (&value_) T(value);
  }
  StatusOr(T &&value)  // NOLINT
      : status_(Status::OK()), has_value_(true) {
    new (&value_) T(std::move(value));
  }

  StatusOr(const StatusOr &other) : status_(other.status_), has_value_(false) {
    if (other.has_value_) {
      new (&value_) T(other.value_);
      has_value_ = true;
    }
  }

  StatusOr(StatusOr &&other) noexcept
      : status_(std::move(other.status_)), has_value_(false) {
    if (other.has_value_) {
      new (&value_) T(std::move(other.value_));
      has_value_ = true;
    }
  }

  // Allow implicit conversion from a StatusOr<U> where U is convertible to T
  // (e.g. StatusOr<Derived> -> StatusOr<Base>).
  template <typename U,
            typename std::enable_if<std::is_convertible<U, T>::value &&
                                        !std::is_same<U, T>::value,
                                    int>::type = 0>
  StatusOr(const StatusOr<U> &other)  // NOLINT
      : status_(other.status()), has_value_(false) {
    if (other.ok()) {
      new (&value_) T(*other);
      has_value_ = true;
    }
  }

  template <typename U,
            typename std::enable_if<std::is_convertible<U, T>::value &&
                                        !std::is_same<U, T>::value,
                                    int>::type = 0>
  StatusOr(StatusOr<U> &&other)  // NOLINT
      : status_(other.status()), has_value_(false) {
    if (other.ok()) {
      new (&value_) T(std::move(*other));
      has_value_ = true;
    }
  }

  StatusOr &operator=(const StatusOr &other) {
    if (this == &other) {
      return *this;
    }
    Clear();
    status_ = other.status_;
    if (other.has_value_) {
      new (&value_) T(other.value_);
      has_value_ = true;
    }
    return *this;
  }

  StatusOr &operator=(StatusOr &&other) noexcept {
    if (this == &other) {
      return *this;
    }
    Clear();
    status_ = std::move(other.status_);
    if (other.has_value_) {
      new (&value_) T(std::move(other.value_));
      has_value_ = true;
    }
    return *this;
  }

  ~StatusOr() { Clear(); }

