+#pragma once
+#include <string>
+#include <utility>
+namespace ray {
+enum class StatusCode : char { OK = 0, KeyError = 2 };
+class Status {
+ public:
+  Status() : code_(StatusCode::OK), ok_(true) {}
+  Status(StatusCode c, std::string m) : code_(c), msg_(std::move(m)), ok_(false) {}
+  static Status OK() { return Status(); }
+  static Status KeyError(std::string m) { return Status(StatusCode::KeyError, std::move(m)); }
+  bool ok() const { return ok_; }
+  StatusCode code() const { return code_; }
+  std::string ToString() const { return msg_; }
+ private:
+  StatusCode code_; std::string msg_; bool ok_;
+};
+}
