@@ -0,0 +1,30 @@
+#include <cassert>
+#include <string>
+#include "ray/common/status_or.h"
+using namespace ray;
+int main() {
+  StatusOr<int> a(5);
+  assert(a.ok() && *a == 5 && a.value() == 5);
+  StatusOr<int> b(Status::KeyError("nope"));
+  assert(!b.ok() && b.code() == StatusCode::KeyError);
+  assert(b.value_or(9) == 9);
+  assert(b.value_or_default() == 0);
+  StatusOr<int> c = a;
+  assert(c == a);
+  assert(b != a);
+  auto r = a.and_then([](int v){ return StatusOr<int>(v*2); });
+  assert(r.ok() && *r == 10);
+  auto r2 = b.and_then([](int v){ return StatusOr<int>(v*2); });
+  assert(!r2.ok());
+  auto r3 = b.or_else([](const Status&){ return StatusOr<int>(42); });
+  assert(r3.ok() && *r3 == 42);
+  swap(a, b);
+  assert(!a.ok() && b.ok() && *b == 5);
+  StatusOr<std::string> s(std::string("hi"));
+  assert(s.ok() && *s == "hi" && s->size() == 2);
+  StatusOr<int> d;
+  assert(d.ok() && *d == 0);
+  if(a) assert(false);
+  if(!b) assert(false);
+  return 0;
+}
