+#include <cassert>
+#include <memory>
+#include <string>
+#include "ray/common/status_or.h"
+using namespace ray;
+struct Base { virtual ~Base()=default; virtual int id() const { return 1; } };
+struct Derived : Base { int id() const override { return 2; } };
+int main() {
+  // Derived -> Base via shared_ptr conversion
+  StatusOr<std::shared_ptr<Derived>> d(std::make_shared<Derived>());
+  StatusOr<std::shared_ptr<Base>> b = d;   // implicit conversion ctor
+  assert(b.ok() && (*b)->id() == 2);
+  // error propagation through conversion
+  StatusOr<std::shared_ptr<Derived>> de(Status::KeyError("x"));
+  StatusOr<std::shared_ptr<Base>> be = de;
+  assert(!be.ok() && be.code() == StatusCode::KeyError);
+  // move-only type
+  StatusOr<std::unique_ptr<int>> u(std::make_unique<int>(7));
+  assert(u.ok() && **u == 7);
+  StatusOr<std::unique_ptr<int>> u2 = std::move(u);
+  assert(u2.ok() && **u2 == 7);
+  auto ptr = std::move(u2).value();
+  assert(*ptr == 7);
+  return 0;
+}
